Content-type: application/json

{
   "additionalModelRequestFields": {{JSON value}},
   "additionalModelResponseFieldPaths": [ "{{string}}" ],
   "guardrailConfig": { 
      "guardrailIdentifier": "{{string}}",
      "guardrailVersion": "{{string}}",
      "streamProcessingMode": "{{string}}",
      "trace": "{{string}}"
   },
   "inferenceConfig": { 
      "maxTokens": {{number}},
      "stopSequences": [ "{{string}}" ],
      "temperature": {{number}},
      "topP": {{number}}
   },
   "messages": [ 
      { 
         "content": [ 
            { ... }
         ],
         "role": "{{string}}"
      }
   ],
   "outputConfig": { 
      "effort": "{{string}}",
      "textFormat": { 
         "structure": { ... },
         "type": "{{string}}"
      }
   },
   "performanceConfig": { 
      "latency": "{{string}}"
   },
   "projectIdentifier": "{{string}}",
   "promptVariables": { 
      "{{string}}" : { ... }
   },
   "requestMetadata": { 
      "{{string}}" : "{{string}}" 
   },
